class Solution { fun sumGame(num:String):Boolean{val half=num.length/2;var leftSum=0;var rightSum=0;var leftQuestions=0;var rightQuestions=0;for(i in num.indices)if(num[i]=='?'){if(i<half)leftQuestions++ else rightQuestions++}else if(i<half)leftSum+=num[i]-'0' else rightSum+=num[i]-'0';if((leftQuestions+rightQuestions)%2==1)return true;return 2*(leftSum-rightSum)!=9*(rightQuestions-leftQuestions)} }
